package br.pucminas.puclim.controller;
import br.pucminas.puclim.entity.*; import br.pucminas.puclim.service.PuclimService;
import jakarta.servlet.http.*; import org.apache.commons.csv.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
import java.io.*; import java.nio.charset.StandardCharsets; import java.time.*; import java.time.format.DateTimeFormatter; import java.util.*;
@RestController @RequestMapping("/api/conta")
public class AccountController {
 private final PuclimService service; private static final ZoneId ZONE=ZoneId.of("America/Sao_Paulo"); private static final DateTimeFormatter DATE=DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm");
 public AccountController(PuclimService service){this.service=service;}
 @GetMapping("/extrato") public List<Map<String,Object>> transactions(@RequestParam(required=false) LocalDate de,@RequestParam(required=false) LocalDate ate,@RequestParam(required=false) String tipo,@RequestParam(required=false) String busca,HttpSession session){return service.transactions(service.current(session,Account.Role.ALUNO,Account.Role.PROFESSOR),de,ate,tipo,busca).stream().map(service::transaction).toList();}
 @GetMapping(value="/extrato/exportar",produces="text/csv") public ResponseEntity<byte[]> export(@RequestParam(required=false) LocalDate de,@RequestParam(required=false) LocalDate ate,@RequestParam(required=false) String tipo,@RequestParam(required=false) String busca,HttpSession session)throws IOException{Account a=service.current(session,Account.Role.ALUNO,Account.Role.PROFESSOR);List<LedgerEntry> rows=service.transactions(a,de,ate,tipo,busca);StringWriter out=new StringWriter();out.write("\uFEFFData;Tipo;Descrição;Pessoa ou empresa;Motivo;Pucoins\r\n");try(CSVPrinter p=new CSVPrinter(out,CSVFormat.DEFAULT.builder().setDelimiter(';').setRecordSeparator("\r\n").get())){for(LedgerEntry x:rows)p.printRecord(safe(DATE.format(x.date.atZone(ZONE))),safe(x.kind),safe(x.description),safe(x.counterpart),safe(x.reason),safe(Long.toString(x.amount)));}return ResponseEntity.ok().contentType(MediaType.parseMediaType("text/csv; charset=UTF-8")).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\"extrato-puclim.csv\"").body(out.toString().getBytes(StandardCharsets.UTF_8));}
 private String safe(String v){String x=Objects.toString(v,"");return x.matches("^[=+\\-@].*")?"'"+x:x;}
 @GetMapping("/notificacoes") public List<Map<String,Object>> notifications(@RequestParam(defaultValue="100")int limite,HttpSession s){return service.notifications(service.current(s),limite).stream().map(n->{Map<String,Object>m=new LinkedHashMap<>();m.put("id",n.id);m.put("subject",n.subject);m.put("body",n.body);m.put("date",n.date);m.put("recipient",n.recipient);m.put("deliveryStatus",n.deliveryStatus);m.put("attempts",n.attempts);return m;}).toList();}
}